            $y--;
        } elseif ($c == 'R') {
            $x++;
        } elseif ($c == 'L') {
            $x--;
        }
        $prefixX[] = $x;
        $prefixY[] = $y;
    }

    $count = 0;
    for ($i = 0; $i <= $n; $i++) {
        for ($j = $i + 1; $j <= $n; $j++) {
            if ($prefixX[$i] == $prefixX[$j] && $prefixY[$i] == $prefixY[$j]) {
                $count++;
            }
        }
    }

    echo $count . "\n";
}

